package com.apnishadi.config;
import com.apnishadi.auth.JwtService; import com.apnishadi.connection.ConversationRepository; import io.jsonwebtoken.Claims; import org.springframework.http.server.ServerHttpRequest; import org.springframework.http.server.ServerHttpResponse; import org.springframework.stereotype.Component; import org.springframework.web.socket.WebSocketHandler; import org.springframework.web.socket.server.HandshakeInterceptor; import java.net.URI; import java.util.Map;
@Component public class JwtWebSocketHandshakeInterceptor implements HandshakeInterceptor { private final JwtService jwt; private final ConversationRepository conversations; public JwtWebSocketHandshakeInterceptor(JwtService j,ConversationRepository c){jwt=j;conversations=c;}
@Override public boolean beforeHandshake(ServerHttpRequest request,ServerHttpResponse response,WebSocketHandler handler,Map<String,Object> attrs){try{URI u=request.getURI();String token=null;String q=u.getRawQuery();if(q!=null)for(String part:q.split("&")){if(part.startsWith("token=")){token=java.net.URLDecoder.decode(part.substring(6),java.nio.charset.StandardCharsets.UTF_8);break;}}if(token==null)return false;Claims claims=jwt.parse(token);Long profileId=((Number)claims.get("profileId")).longValue();String path=u.getPath();Long conversationId=Long.valueOf(path.substring(path.lastIndexOf('/')+1));var c=conversations.findById(conversationId).orElse(null);if(c==null||(!c.getProfileOne().getId().equals(profileId)&&!c.getProfileTwo().getId().equals(profileId)))return false;attrs.put("profileId",profileId);attrs.put("conversationId",conversationId);return true;}catch(Exception e){return false;}}
@Override public void afterHandshake(ServerHttpRequest r,ServerHttpResponse s,WebSocketHandler h,Exception e){}
}
